  [ [[v5748eaic9oku]] ] = { t = [[快枪与借机攻击]], q = [=[拥有快枪（第119页）和[[战斗反射]]的角色，假设装填远程武器是自由动作，能用远程武器进行多次借机攻击吗？]=], a = [[可以。只要你能以自由动作装填武器，就可以把装填作为你用快枪专长进行的远程借机攻击的一部分。]], book = [[极限战斗]], date = [[2011/01/10]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1g1#v5748eaic9oku]], cat = [[FAQ]], ai = false, pages = { [[快枪]] } },
